// ─── File: ObserverDemo.java ───
package com.bank.observer;

import java.lang.ref.WeakReference;
import java.math.BigDecimal;
import java.util.logging.*;

public class ObserverDemo {
    private static final Logger log = Logger.getLogger(ObserverDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PricePublisher publisher = new PricePublisher();

        // LEAK: subscribe many short-lived observers and NEVER unsubscribe
        for (int i = 0; i < 1000; i++) {
            final int id = i;
            publisher.subscribeLeaky(price -> { /* request-scoped observer */ });
        }
        publisher.publish("RELIANCE", new BigDecimal("2450"));
        log.warning("LEAKY list size after 1000 forgotten subs: " + publisher.leakySize());

        // SAFE: subscription handle closed in finally keeps the list bounded
        for (int i = 0; i < 1000; i++) {
            PricePublisher.Subscription sub = publisher.subscribe(
                price -> { /* react to price */ });
            try {
                // ... use the subscription for one request ...
            } finally {
                sub.close();     // guaranteed unsubscribe
            }
        }
        log.info(() -> "SAFE list size after 1000 handled subs: " + publisher.size() + " (expect 0)");

        // WEAK: forgotten observer can still be garbage-collected
        WeakPricePublisher weak = new WeakPricePublisher();
        PriceListener strong = price -> Logger.getLogger("PRICE").info("tick " + price);
        weak.subscribe(strong);
        weak.publish(new BigDecimal("2451"));        // fires: strong ref alive
        strong = null;                                // drop the only strong ref
        System.gc();
        try { Thread.sleep(50); } catch (InterruptedException ignored) {}
        weak.publish(new BigDecimal("2452"));        // dead observer purged, no fire
        log.info(() -> "WEAK list size after GC: " + weak.size() + " (expect 0)");
    }
}

// ─── Observer interface ───
@FunctionalInterface
interface PriceListener { void onPrice(BigDecimal price); }

// ─── Subject with strong refs; provides a closable Subscription handle ───
class PricePublisher {
    private final java.util.List<PriceListener> leaky = new java.util.ArrayList<>();
    private final java.util.List<PriceListener> listeners = new java.util.concurrent.CopyOnWriteArrayList<>();

    // BAD: no way to remove → lapsed listener leak
    void subscribeLeaky(PriceListener l) { leaky.add(l); }
    int leakySize() { return leaky.size(); }

    // GOOD: returns a handle whose close() removes the listener
    Subscription subscribe(PriceListener l) {
        listeners.add(l);
        return () -> listeners.remove(l);
    }
    void publish(String symbol, BigDecimal price) { listeners.forEach(l -> l.onPrice(price)); }
    int size() { return listeners.size(); }

    // AutoCloseable so callers can use try-with-resources or finally
    interface Subscription extends AutoCloseable { void close(); }
}

// ─── Subject with weak refs; GC can reclaim forgotten observers ───
class WeakPricePublisher {
    private final java.util.List<WeakReference<PriceListener>> refs = new java.util.concurrent.CopyOnWriteArrayList<>();
    void subscribe(PriceListener l) { refs.add(new WeakReference<>(l)); }
    void publish(BigDecimal price) {
        refs.removeIf(ref -> ref.get() == null);      // purge dead observers
        for (WeakReference<PriceListener> ref : refs) {
            PriceListener l = ref.get();
            if (l != null) l.onPrice(price);
        }
    }
    int size() { refs.removeIf(ref -> ref.get() == null); return refs.size(); }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
```

Note: the Subscription interface is nested only to keep it tightly bound to its publisher in this single-file demo; the GC-based weak-reference behavior is timing dependent, so the printed weak size is the expected result after collection, which the JVM performs promptly here under System.gc.
